import React,{useEffect,useMemo,useState} from 'react';
import {ArrowRight,ArrowDownToLine,ExternalLink,Search,Info,Building2,MapPin,GitCompareArrows,ShieldCheck,FileText,Database} from 'lucide-react';
import type {EChartsOption} from 'echarts';
import {Chart} from './Chart';
import type {Dataset} from './types';
import type {PlatformData,AcademicRecord,PlaceRecord,SiteRecord,OfficialSource,ResearchData,University} from './platformTypes';
import {exportRows,exportJSON,htmlReport,pdfReport} from './platformExport';
import type {ReportSpec} from './platformExport';
import {MexicoMap} from './MexicoMap';
import {ReceivingAnalysis} from './ReceivingAnalysis';
import {OfferComposition} from './OfferComposition';
import {AcademicLongitudinal} from './AcademicLongitudinal';
import {Trends} from './Trends';
import {UniversityAnalysis} from './UniversityAnalysis';

const palette=['#087f83','#617be3','#bd772f','#ad5da7','#4193bd'];
const fmt=(n:number|null|undefined,d=0)=>n==null?'No disponible':n.toLocaleString('es-MX',{minimumFractionDigits:d,maximumFractionDigits:d});
const normalized=(s:string)=>s.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();
const unique=(a:string[])=>[...new Set(a)].sort((a,b)=>a.localeCompare(b,'es'));
const emptyData:PlatformData={version:'2.0.0',audit_date:'2026-10-31',academic_years:[],national:[],universities:[],academic_records:[],receiving:[],receiving_summary:[],sites:[],sources:[],issues:[],coverage:{}};
function useResource<T>(name:string){const [loaded,setLoaded]=useState<{name:string;data:T}|null>(null);const [error,setError]=useState('');useEffect(()=>{const controller=new AbortController();setError('');fetch(`${import.meta.env.BASE_URL}data/${name}.json`,{signal:controller.signal}).then(r=>{if(!r.ok)throw Error(`No se pudo cargar ${name}.`);return r.json();}).then(data=>setLoaded({name,data})).catch(e=>{if(e.name!=='AbortError')setError(String(e));});return()=>controller.abort();},[name]);return {data:loaded?.name===name?loaded.data:null,error};}
function Heading({label,title,description,children}:{label:string;title:string;description:string;children?:React.ReactNode}){return <div className="page-heading"><div><div className="eyebrow"><span/>{label}</div><h1>{title}</h1><p>{description}</p></div><div className="heading-actions">{children}</div></div>;}
function Notice({children}:{children:React.ReactNode}){return <div className="notice"><Info size={18}/><div>{children}</div></div>;}
function Blocked({children}:{children:React.ReactNode}){return <div className="empty-state"><ShieldCheck size={28}/><strong>Análisis condicionado a evidencia suficiente</strong><p>{children}</p><a href="#/methodology">Consultar metodología <ArrowRight size={14}/></a></div>;}
function Metrics({values}:{values:{label:string;value:React.ReactNode;note?:string}[]}){return <div className="metrics">{values.map(v=><div key={v.label}><small>{v.label}</small><strong>{v.value}</strong>{v.note&&<small>{v.note}</small>}</div>)}</div>;}
function Select({label,value,values,onChange,all}:{label:string;value:string;values:string[];onChange:(s:string)=>void;all?:string}){return <label className="platform-select">{label}<select value={value} onChange={e=>onChange(e.target.value)}>{all&&<option value="">{all}</option>}{values.map(v=><option key={v}>{v}</option>)}</select></label>;}
function SourceLink({id,data,page}:{id:string;data:PlatformData;page?:number|null}){const src=data.sources.find(s=>s.id===id);return src?<a href={src.url+(page?`#page=${page}`:'')} target="_blank" rel="noreferrer">CIFRHS {src.year}{page?` · p. ${page}`:''} <ExternalLink size={11}/></a>:<span>Fuente no disponible</span>;}
function Table({headers,rows,caption}:{headers:string[];rows:React.ReactNode[][];caption:string}){const [page,setPage]=useState(0);const pageSize=40;const pages=Math.max(1,Math.ceil(rows.length/pageSize));const safePage=Math.min(page,pages-1);return <div className="table-block"><div className="table-scroll" role="region" tabIndex={0} aria-label={caption}><table><caption>{caption} · {fmt(rows.length)} filas</caption><thead><tr>{headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.slice(safePage*pageSize,(safePage+1)*pageSize).map((row,i)=><tr key={i}>{row.map((c,j)=>j===0?<th scope="row" key={j}>{c}</th>:<td key={j}>{c}</td>)}</tr>)}</tbody></table></div>{!rows.length&&<p className="no-results">No hay registros que coincidan con los filtros.</p>}{pages>1&&<div className="pagination"><button className="secondary" disabled={safePage===0} onClick={()=>setPage(safePage-1)}>Anterior</button><span>Página {safePage+1} de {pages}</span><button className="secondary" disabled={safePage>=pages-1} onClick={()=>setPage(safePage+1)}>Siguiente</button></div>}</div>;}
function Bar({names,values,label,dark,unit=''}:{names:string[];values:number[];label:string;dark:boolean;unit?:string}){const option:EChartsOption={grid:{left:8,right:55,top:30,bottom:35,containLabel:true},tooltip:{trigger:'axis'},xAxis:{type:'value',name:unit},yAxis:{type:'category',data:names,axisLabel:{width:180,overflow:'truncate',fontSize:11}},series:[{type:'bar',barMaxWidth:23,itemStyle:{color:palette[0]},data:values,label:{show:true,position:'right',formatter:p=>fmt(Number(p.value),1),fontSize:10}}]};return <Chart option={option} label={label} dark={dark} height={Math.max(260,Math.min(500,names.length*35+70))}/>;}

type Props={path:string;params:URLSearchParams;update:(key:string,value:string)=>void;dark:boolean;specialties:Dataset};
export function Platform({path,params,update,dark,specialties}:Props){
 const resource=path==='/sources-all'||path==='/methodology'?'platform-sources':path.startsWith('/receiving')||path.startsWith('/hospitals')?'receiving':path.startsWith('/universities')||path==='/university-compare'||path==='/explorer'||path==='/reports'||path==='/research'?'academic':path==='/atlas'?'atlas':'national';
 const {data:partition,error}=useResource<Partial<PlatformData>>(resource);const data={...emptyData,...partition};
 if(error)return <Notice>{error} <button onClick={()=>location.reload()}>Reintentar</button></Notice>;
 if(!partition)return <div className="empty-state" role="status"><Database size={30}/><p>Cargando datos oficiales del módulo…</p></div>;
 const props={data,params,update,dark};
 if(path==='/')return <Home {...props} specialties={specialties}/>;
 if(path==='/national')return <NationalPage {...props}/>;
 if(path.startsWith('/universities/'))return <UniversityProfile {...props} id={decodeURIComponent(path.split('/')[2])}/>;
 if(path==='/universities')return <Universities {...props}/>;
 if(path==='/university-compare')return <UniversityCompare {...props}/>;
 if(path.startsWith('/receiving/'))return <Receiving {...props} profileId={decodeURIComponent(path.split('/')[2])}/>;
 if(path==='/receiving')return <Receiving {...props}/>;
 if(path==='/receiving-compare')return <Receiving {...props} compare/>;
 if(path.startsWith('/hospitals'))return <Hospitals {...props} id={path.split('/')[2]}/>;
 if(path==='/atlas')return <Atlas {...props}/>;
 if(path==='/research')return <Research {...props}/>;
 if(path==='/predictions'||path==='/lab')return <Trends params={params} update={update} dark={dark}/>;
 if(path==='/explorer')return <Explorer {...props}/>;
 if(path==='/reports')return <Reports {...props}/>;
 if(path==='/sources-all')return <AllSources {...props}/>;
 if(path==='/methodology')return <Methodology/>;
 return <Notice>Página no encontrada. <a href="#/">Ir al inicio</a></Notice>;
}
type PageProps={data:PlatformData;params:URLSearchParams;update:(key:string,value:string)=>void;dark:boolean};
function academicYear(data:PlatformData,params:URLSearchParams){const requested=Number(params.get('year'));return data.academic_years.includes(requested)?requested:data.academic_years.at(-1)!;}

function Home({data,dark,specialties}:PageProps&{specialties:Dataset}){const latest=data.national.at(-1)!;return <><Heading label="OBSERVATORIO NACIONAL DEL ENARM" title={`${data.academic_years.length} ediciones. Nuevas perspectivas.`} description="Una plataforma pública para estudiar resultados, universidades de procedencia y oportunidades de formación médica especializada."/><section className="intro-band platform-hero"><div><span className="tag">by Doctor Data MX · DATOS ABIERTOS</span><h2>La historia del ENARM,<br/><em>explorada con ciencia de datos.</em></h2><p>Del resultado académico a la distribución de plazas. Fuentes oficiales, métodos reproducibles y preguntas con contexto.</p><div className="hero-links"><a className="primary" href="#/national">Explorar resultados <ArrowRight size={16}/></a><a className="hero-secondary" href="#/receiving">Instituciones receptoras <ArrowRight size={16}/></a></div><p className="hero-contact">Contacto: <a href="mailto:dr.avalos.mi.ds@gmail.com">dr.avalos.mi.ds@gmail.com</a></p></div><div className="hero-index"><span>UN SISTEMA, DISTINTAS UNIDADES DE ANÁLISIS</span>{[['01','Universidad de procedencia','¿De dónde provienen los sustentantes?'],['02','Especialidad','¿Qué umbrales se publican?'],['03','Institución y sede receptora','¿Dónde se ofrece la formación?']].map(([n,h,p])=><div key={n}><b>{n}</b><section><h3>{h}</h3><p>{p}</p></section></div>)}</div></section><Metrics values={[{label:'Participaciones registradas',value:fmt(data.national.reduce((n,r)=>n+r.examined,0)),note:'Suma entre ediciones; no personas únicas'},{label:`Tasa agregada · ${latest.year}`,value:fmt(latest.rate,1)+'%',note:'Seleccionados / sustentantes de filas extraídas'},{label:'Cobertura académica',value:`${data.academic_years[0]}–${latest.year}`,note:`${data.academic_years.length} ediciones oficiales`},{label:'Especialidades catalogadas',value:specialties.specialties.length,note:'Puntajes 2022–2025; categoría mexicana'}]}/><Notice>ENARM Watcher es una iniciativa independiente de análisis de datos. No representa ni está afiliada oficialmente a la CIFRHS o a la Secretaría de Salud. La ubicación de una universidad y el aval académico de una sede describen unidades diferentes.</Notice><section className="panel"><div className="panel-title"><div><span className="kicker">PANORAMA LONGITUDINAL</span><h2>Participación en las ediciones incorporadas</h2><p>Suma de sustentantes publicados por escuela, categoría mexicana. Consulta cobertura y denominadores en el panorama.</p></div><a className="text-link" href="#/national">Ver panorama <ArrowRight size={15}/></a></div><Chart dark={dark} label="Sustentantes agregados por edición. Datos exactos en Panorama Nacional." option={{tooltip:{trigger:'axis'},grid:{left:55,right:20,top:25,bottom:35},xAxis:{type:'category',data:data.national.map(r=>String(r.year)),axisLabel:{interval:3}},yAxis:{type:'value',name:'Sustentantes'},series:[{type:'bar',itemStyle:{color:'#087f83'},data:data.national.map(r=>r.examined)}]}}/></section><div className="module-grid">{[['Universidades','Perfiles, denominadores, tasas e intervalos descriptivos.','/universities'],['Specialty Intelligence','Umbrales, comparación y elegibilidad para análisis longitudinal.','/specialty'],['Instituciones Receptoras','Plazas por institución, especialidad, entidad y sede.','/receiving'],['Atlas ENARM','Geografía de procedencia académica y oferta receptora.','/atlas'],['Laboratorio de Ciencia de Datos','Asociaciones, concentración, estabilización y frontera de Pareto.','/research'],['Explorador de Datos','Filtra, ordena y descarga registros con trazabilidad.','/explorer']].map(([h,p,url])=><a className="panel module-card" href={'#'+url} key={url}><Building2 size={23}/><h2>{h}</h2><p>{p}</p><span>Explorar <ArrowRight size={15}/></span></a>)}</div></>;}

function NationalPage({data,params,update,dark}:PageProps){const year=academicYear(data,params);const metric=params.get('metric')||'examined';const row=data.national.find(r=>r.year===year)!;const key=metric as 'examined'|'selected'|'rate'|'score';return <><Heading label="PANORAMA NACIONAL" title="El ENARM, edición por edición." description="Agregados reproducibles de las filas publicadas por escuela. No se combinan categorías mexicana y extranjera."><button className="secondary" onClick={()=>exportRows('panorama-nacional',data.national as unknown as Record<string,unknown>[])}><ArrowDownToLine size={16}/> CSV</button></Heading><div className="platform-filters"><Select label="Edición" value={String(year)} values={data.academic_years.map(String)} onChange={v=>update('year',v)}/><Select label="Indicador" value={metric} values={['examined','selected','rate','score']} onChange={v=>update('metric',v)}/></div><Metrics values={[{label:`Sustentantes ${year}`,value:fmt(row.examined)},{label:`Seleccionados ${year}`,value:fmt(row.selected),note:!row.selected_complete?`${fmt(row.selected_observed_subtotal)} en filas informadas; ${row.selected_missing_rows} sin dato. No es total completo.`:undefined},{label:'Tasa agregada',value:row.rate==null?'No disponible':fmt(row.rate,2)+'%'},{label:'Promedio ponderado',value:fmt(row.score,3),note:'Solo medias; nunca promedio de medianas'}]}/><Notice>Indicadores: examined = sustentantes; selected = seleccionados; rate = tasa (%); score = promedio ponderado por sustentantes. Puntajes y tasas se muestran como observaciones independientes: su comparabilidad longitudinal no está acreditada. La composición de escuelas y las reglas de selección cambian entre ediciones.</Notice><section className="panel"><h2>{metric==='examined'?'Sustentantes':metric==='selected'?'Seleccionados':metric==='rate'?'Tasa agregada de selección':'Promedio ponderado'} · serie observada</h2><Chart dark={dark} label="Serie nacional, con tabla accesible a continuación." option={{tooltip:{trigger:'axis'},grid:{left:55,right:25,top:35,bottom:45},xAxis:{type:'category',data:data.national.map(r=>String(r.year)),axisLabel:{interval:2}},yAxis:{type:'value',name:metric==='rate'?'Porcentaje':metric==='score'?'Puntos':'Participaciones',max:metric==='rate'||metric==='score'?100:undefined},series:[{type:metric==='examined'||metric==='selected'?'bar':'scatter',symbolSize:10,itemStyle:{color:palette[0]},data:data.national.map(r=>r[key])}]}}/></section><section className="panel"><Table caption="Agregados calculados desde las tablas de categoría mexicana" headers={['Edición','Sustentantes','Seleccionados','Tasa (%)','Promedio ponderado','Filas publicadas']} rows={data.national.map(r=>[r.year,fmt(r.examined),fmt(r.selected),fmt(r.rate,2),fmt(r.score,3),r.institutions])}/></section><Notice>En 2005 y 2006 se conservan las medianas originales: no se construye una media nacional a partir de ellas. Si hay conteos faltantes o controles de conciliación pendientes, el agregado de seleccionados se muestra incompleto. En 2024 la fila de ESC. MÉDICO - NAVAL SEMAR publica tres sustentantes y deja seleccionados en blanco; no se sustituye por cero ni se calcula una tasa nacional completa. Los resultados académicos incorporados llegan a {data.academic_years.at(-1)}; los puntajes y la oferta de especialidades tienen su propia cobertura.</Notice></>;}

function universityFilters(data:PlatformData,params:URLSearchParams){const year=academicYear(data,params);const q=normalized(params.get('q')||'');const state=params.get('state')||'';const min=Math.max(0,Number(params.get('min'))||0);const metric=params.get('metric')||'rate';const rows=data.academic_records.filter(r=>r.year===year&&r.examined>=min&&(!state||r.state===state)&&normalized(r.name).includes(q));rows.sort((a,b)=>(b[metric as 'examined'|'rate'|'score']??-1)-(a[metric as 'examined'|'rate'|'score']??-1)||a.name.localeCompare(b.name));const reference=data.academic_records.filter(r=>r.year===year&&r.examined>=min&&(!state||r.state===state)&&r[metric as 'examined'|'rate'|'score']!=null);const ranks:Record<string,{rank:number;percentile:number}>={};for(const r of reference){const value=r[metric as 'examined'|'rate'|'score']!;const greater=reference.filter(o=>o[metric as 'examined'|'rate'|'score']!>value).length;const tied=reference.filter(o=>o[metric as 'examined'|'rate'|'score']===value).length;const rank=greater+(tied+1)/2;ranks[r.id]={rank,percentile:reference.length>1?100*(reference.length-rank)/(reference.length-1):100};}return {year,q,state,min,metric,rows,ranks};}
function UniversityControls({data,params,update}:PageProps){const {year,state,min,metric}=universityFilters(data,params);return <div className="platform-filters"><label className="search"><Search size={16}/><input aria-label="Buscar universidad" placeholder="Buscar facultad o campus…" value={params.get('q')||''} onChange={e=>update('q',e.target.value)}/></label><Select label="Edición" value={String(year)} values={data.academic_years.map(String)} onChange={v=>update('year',v)}/><Select label="Entidad de escuela" value={state} values={unique(data.academic_records.map(r=>r.state).filter(Boolean) as string[])} all="Todas" onChange={v=>update('state',v)}/><label className="platform-select">Sustentantes mínimos<input type="number" min="0" value={min} onChange={e=>update('min',e.target.value)}/></label><Select label="Ordenar por" value={metric} values={['rate','score','examined']} onChange={v=>update('metric',v)}/></div>;}
function Universities(props:PageProps){const {data,params}=props;const {year,rows,ranks}=universityFilters(data,params);return <><Heading label="UNIVERSIDADES DE PROCEDENCIA" title="Cada institución, con denominadores." description="Facultades, escuelas y campus según su denominación en la fuente. Consulta volumen, tasas y puntajes dentro de cada edición."><a className="secondary" href="#/university-compare"><GitCompareArrows size={15}/> Comparar hasta cinco</a><button className="secondary" onClick={()=>exportRows('universidades-filtradas',rows as unknown as Record<string,unknown>[])}><ArrowDownToLine size={16}/> CSV filtrado</button></Heading><UniversityControls {...props}/><Notice>El orden por tasa o puntaje no estima calidad causal de la formación. Las tasas incluyen denominadores y un filtro de volumen mínimo; los puntajes identifican si la fuente publica media o mediana. Las denominaciones históricas no se fusionan por similitud difusa. Rango y percentil usan la edición, entidad y volumen mínimo filtrados; buscar por nombre no cambia ese universo. Empates con rango medio.</Notice><section className="panel"><Table caption={`Universidades · categoría mexicana · ${year}`} headers={['Facultad / escuela','Entidad fuente','Sustentantes','Seleccionados','Tasa (%)','Puntaje','Estadístico','Rango','Percentil','Fuente']} rows={rows.map(r=>[<a href={'#/universities/'+r.id}>{r.name}</a>,r.state||'No identificada',fmt(r.examined),fmt(r.selected),fmt(r.rate,2),fmt(r.score,3),r.score_statistic==='median'?'Mediana':'Media',fmt(ranks[r.id]?.rank,1),fmt(ranks[r.id]?.percentile,1),<SourceLink id={r.source_id} page={r.page} data={data}/>])}/></section></>;}

function universityReport(u:University,data:PlatformData):ReportSpec{const latest=u.records.at(-1)!;return {title:u.name,scope:`Universidad de procedencia · ${u.state||'sin entidad identificada'} · categoría mexicana`,summary:[`${u.records.length} ediciones ${u.identity_link?'con equivalencias documentadas':'con la misma clave normalizada'}. Última observación ${latest.year}: ${fmt(latest.examined)} sustentantes, ${fmt(latest.selected)} seleccionados y tasa ${fmt(latest.rate,2)}%.`,'Los puntajes conservan la definición de media o mediana del documento. La comparabilidad longitudinal no está acreditada.'],headers:['Edición','Sustentantes','Seleccionados','Tasa (%)','Puntaje','Estadístico'],rows:u.records.map(r=>[r.year,r.examined,r.selected,r.rate==null?null:fmt(r.rate,2),r.score,r.score_statistic]),sources:data.sources.filter(s=>u.records.some(r=>r.source_id===s.id)),limitations:['Tasa = 100 × seleccionados / sustentantes de la misma fila, edición y categoría.','Intervalos Wilson al 95% bajo un modelo binomial descriptivo; no son intervalos predictivos.','La identidad normalizada no garantiza equivalencia entre denominaciones históricas diferentes. Se preservan campus y fuente.','No se infieren especialidades, destinos hospitalarios, causalidad o probabilidades individuales.','Sin proyecciones hasta validar comparabilidad y suficiencia temporal.'],bars:u.records.slice(-8).filter(r=>r.rate!=null).map(r=>({name:String(r.year),value:r.rate!}))};}
function UniversityProfile({data,id,params,update,dark}:PageProps&{id:string}){const u=data.universities.find(u=>u.id===id||u.identity_link?.alias_ids.includes(id));if(!u)return <Notice>Perfil no encontrado. <a href="#/universities">Volver a universidades</a></Notice>;const requested=Number(params.get('year'));const year=u.records.some(r=>r.year===requested)?requested:u.records.at(-1)!.year;const row=u.records.find(r=>r.year===year)!;const ci=row.rate_interval95;const report=universityReport(u,data);return <><a className="back" href="#/universities">Universidades <ArrowRight size={14}/> Perfil</a><Heading label="UNIVERSIDAD DE PROCEDENCIA" title={u.name} description={`${u.state||'Entidad no identificada'} · ${u.records.length} ediciones ${u.identity_link?'vinculadas mediante equivalencias documentadas':'con la misma denominación normalizada'}. No se infieren equivalencias con otros campus.`}><button className="secondary" onClick={()=>htmlReport(report)}>Informe HTML</button><button className="primary" onClick={()=>void pdfReport(report)}><ArrowDownToLine size={15}/> PDF</button></Heading><Select label="Edición" value={String(year)} values={u.records.map(r=>String(r.year))} onChange={v=>update('year',v)}/><Metrics values={[{label:'Sustentantes',value:fmt(row.examined)},{label:'Seleccionados',value:fmt(row.selected)},{label:'Tasa observada',value:row.rate==null?'No disponible':fmt(row.rate,2)+'%',note:ci?`Wilson 95%: ${fmt(ci[0],2)}–${fmt(ci[1],2)}%`:'Intervalo no disponible'},{label:row.score_statistic==='median'?'Mediana publicada':'Promedio publicado',value:fmt(row.score,3),note:'Puntos; comparabilidad histórica pendiente'}]}/><UniversityAnalysis university={u} data={data} year={year} dark={dark}/><section className="panel"><Table caption="Historia publicada y trazabilidad" headers={['Edición','Sustentantes','Seleccionados','Tasa (%)','Puntaje','Tipo','Fuente']} rows={u.records.map(r=>[r.year,fmt(r.examined),fmt(r.selected),fmt(r.rate,2),fmt(r.score,3),r.score_statistic==='median'?'Mediana':'Media',<SourceLink id={r.source_id} page={r.page} data={data}/>])}/></section><Notice>El intervalo Wilson describe incertidumbre bajo el supuesto binomial; no recoge todas las diferencias de composición y no predice la selección de una persona. No se interpreta el desempeño como calidad causal. El estado es el reportado para la escuela y puede contener inconsistencias del documento original.</Notice></>;}

function UniversityCompare({data,params,update,dark}:PageProps){const selected=(params.get('u')||'').split(',').filter(Boolean).map(id=>data.universities.find(u=>u.id===id||u.identity_link?.alias_ids.includes(id))?.id||id).filter((id,i,all)=>all.indexOf(id)===i).slice(0,5);const picked=data.universities.filter(u=>selected.includes(u.id));const q=normalized(params.get('q')||'');const metric=params.get('metric')==='examined'?'examined':'rate';const years=unique(picked.flatMap(u=>u.records.map(r=>String(r.year))));return <><Heading label="COMPARADOR DE PROCEDENCIA" title="Hasta cinco perspectivas académicas." description="Comparación de tasas y volumen, con denominadores, cobertura y observaciones por edición."><button className="secondary" disabled={!picked.length} onClick={()=>exportRows('comparacion-universidades',picked.flatMap(u=>u.records) as unknown as Record<string,unknown>[])}>CSV</button></Heading><section className="panel"><label className="search"><Search size={16}/><input aria-label="Buscar en el comparador universitario" value={params.get('q')||''} placeholder="Buscar para añadir una universidad…" onChange={e=>update('q',e.target.value)}/></label><p>{picked.length} / 5 seleccionadas. Las casillas permiten retirar perfiles.</p><fieldset className="selection"><legend>Selección de universidades</legend>{data.universities.filter(u=>normalized(u.name).includes(q)||selected.includes(u.id)).map(u=><label key={u.id}><input type="checkbox" checked={selected.includes(u.id)} disabled={!selected.includes(u.id)&&picked.length>=5} onChange={()=>update('u',selected.includes(u.id)?selected.filter(id=>id!==u.id).join(','):[...selected,u.id].join(','))}/>{u.name} · {u.state||'sin entidad'}</label>)}</fieldset></section><Select label="Indicador" value={metric} values={['rate','examined']} onChange={v=>update('metric',v)}/><section className="panel">{picked.length?<Chart dark={dark} label="Comparación de observaciones universitarias con valores exactos en la tabla." height={400} option={{tooltip:{trigger:'axis'},legend:{bottom:0,type:'scroll'},grid:{left:45,right:20,top:30,bottom:90},xAxis:{type:'category',data:years,axisLabel:{interval:2}},yAxis:{type:'value',max:metric==='rate'?100:undefined,name:metric==='rate'?'Tasa (%)':'Sustentantes'},series:picked.map((u,i)=>({name:u.name,type:'scatter',symbolSize:10,itemStyle:{color:palette[i]},data:years.map(y=>u.records.find(r=>r.year===Number(y))?.[metric]??null)}))}}/>:<Blocked>Selecciona entre una y cinco universidades para mostrar la comparación.</Blocked>}</section><section className="panel"><Table caption="Registros seleccionados; faltantes no imputados" headers={['Institución','Edición','Sustentantes','Seleccionados','Tasa (%)','Fuente']} rows={picked.flatMap(u=>u.records.map(r=>[u.name,r.year,fmt(r.examined),fmt(r.selected),fmt(r.rate,2),<SourceLink data={data} id={r.source_id} page={r.page}/>]))}/></section><Notice>Las series se presentan como observaciones independientes. No se equiparan puntajes históricos ni se infieren cruces con especialidades o instituciones receptoras.</Notice></>;}

function receivingFilters(data:PlatformData,params:URLSearchParams,profileId?:string){const years=unique(data.receiving.map(r=>String(r.year)));const year=years.includes(params.get('year')||'')?Number(params.get('year')):Number(years.at(-1));const institution=profileId||params.get('institution')||'';const specialty=params.get('specialty')||'';const state=params.get('state')||'';const rows=data.receiving.filter(r=>r.year===year&&(!institution||r.institution_id===institution)&&(!specialty||r.specialty_id===specialty));const sites=data.sites.filter(r=>r.year===year&&(!institution||r.institution_id===institution)&&(!specialty||r.specialty_id===specialty)&&(!state||r.state===state));return {years,year,institution,specialty,state,rows,sites};}
function groupedPlaces(rows:PlaceRecord[]|SiteRecord[],field:'institution_id'|'state'|'specialty_id'){const map=new Map<string,{id:string;name:string;value:number}>();for(const r of rows){const key=String(r[field]||'No identificado');const name=field==='institution_id'?r.institution_name:field==='specialty_id'?r.specialty:String(r[field]||'No identificado');const group=map.get(key)||{id:key,name,value:0};group.value+=r.places;map.set(key,group);}return [...map.values()].sort((a,b)=>b.value-a.value);}
function concentrationValues(values:number[]){const sorted=[...values].sort((a,b)=>b-a);const total=values.reduce((a,b)=>a+b,0);return {total,hhi:total?values.reduce((n,v)=>n+(v/total)**2,0)*10000:null,top3:total?sorted.slice(0,3).reduce((a,b)=>a+b,0)/total*100:null,positive:values.filter(v=>v>0).length};}
function placeReport(title:string,rows:PlaceRecord[]|SiteRecord[],data:PlatformData):ReportSpec{return {title,scope:'Oferta publicada R1 · categoría mexicana · snapshots documentales',summary:[`${fmt(rows.reduce((n,r)=>n+r.places,0))} plazas en los registros filtrados. No se suman matrices y listados de sedes. No se interpreta la oferta como asignación, ocupación o incorporación de residentes.`],headers:['Edición','Institución','Especialidad','Entidad','Plazas'],rows:rows.map(r=>[r.year,r.institution_name,r.specialty,r.state,r.places]),sources:data.sources.filter(s=>rows.some(r=>r.source_id===s.id)),limitations:['Matriz institucional y detalle por sedes son niveles alternativos de la misma oferta; nunca se suman entre sí.','Corte documental no identificado; no se mezclan rondas, categorías o tipos de plaza.','La oferta no mide calidad educativa, prestigio, condiciones laborales o suficiencia de especialistas.','Entidad sede y subsede se conservan separadas; CLUES y coordenadas no se infieren por nombre.','Cambios entre snapshots anuales pueden reflejar nomenclatura o composición; sin inferencia causal ni pronóstico.'],bars:groupedPlaces(rows,'specialty_id').slice(0,8).map(r=>({name:r.name,value:r.value}))};}
function Receiving({data,params,update,dark,profileId,compare=false}:PageProps&{profileId?:string;compare?:boolean}){
 const {years,year,institution,specialty,state,rows,sites}=receivingFilters(data,params,profileId);const allInstitutions=groupedPlaces(data.receiving.filter(r=>r.year===year),'institution_id');const allSpecialties=groupedPlaces(data.receiving.filter(r=>r.year===year),'specialty_id');const selected=(params.get('r')||'imss,ssa,issste').split(',').filter(Boolean).slice(0,5);const records=compare?rows.filter(r=>selected.includes(r.institution_id)):rows;const groups=groupedPlaces(records,'institution_id');const stats=concentrationValues(groups.map(g=>g.value));const within=concentrationValues(groupedPlaces(records,'specialty_id').map(g=>g.value));const unavailableGeo=Boolean(state&&year!==2025);const instName=allInstitutions.find(i=>i.id===institution)?.name;const totalAll=data.receiving.filter(r=>r.year===year).reduce((n,r)=>n+r.places,0);const spec=placeReport(instName||'Instituciones receptoras',state?sites:records,data);
 const filtered=state?sites:records;const dimensions=groupedPlaces(filtered,profileId?'specialty_id':'institution_id').filter(r=>r.value>0).slice(0,12).reverse();const snapshotYears=years.map(Number);
 const matrixNames=allSpecialties.map(s=>s.name);const topGroups=groups.slice(0,8);const heat=topGroups.flatMap((g,i)=>allSpecialties.map((s,j)=>[j,i,records.filter(r=>r.institution_id===g.id&&r.specialty_id===s.id).reduce((n,r)=>n+r.places,0)]));
 return <><Heading label="INSTITUTIONAL RESIDENCY INTELLIGENCE" title={compare?'Comparador de instituciones':instName||'Instituciones Receptoras'} description="Distribución nacional de plazas y oportunidades de formación médica especializada. Oferta publicada, con trazabilidad de documento y nivel de agregación."><button className="secondary" onClick={()=>exportRows('plazas-filtradas',filtered as unknown as Record<string,unknown>[])}><ArrowDownToLine size={15}/> CSV</button><button className="secondary" onClick={()=>htmlReport(spec)}>Informe HTML</button><button className="primary" onClick={()=>void pdfReport(spec)}>PDF</button></Heading><div className="platform-filters"><Select label="Edición" value={String(year)} values={years} onChange={v=>{update('year',v);}}/>{!profileId&&!compare&&<label className="platform-select">Institución<select value={institution} onChange={e=>update('institution',e.target.value)}><option value="">Todas</option>{allInstitutions.map(i=><option key={i.id} value={i.id}>{i.name}</option>)}</select></label>}<label className="platform-select">Especialidad<select value={specialty} onChange={e=>update('specialty',e.target.value)}><option value="">Todas</option>{allSpecialties.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><Select label="Entidad sede · solo 2025" value={state} values={unique(data.sites.map(r=>r.state))} all="Todas / matriz nacional" onChange={v=>update('state',v)}/></div>{compare&&<section className="panel"><fieldset className="selection"><legend>Seleccionar hasta cinco instituciones ({selected.length}/5)</legend>{allInstitutions.map(i=><label key={i.id}><input type="checkbox" checked={selected.includes(i.id)} disabled={!selected.includes(i.id)&&selected.length>=5} onChange={()=>update('r',selected.includes(i.id)?selected.filter(id=>id!==i.id).join(','):[...selected,i.id].join(','))}/>{i.name}</label>)}</fieldset></section>}
 <Metrics values={[{label:state?'Plazas en sedes filtradas':`Plazas en matriz · ${year}`,value:unavailableGeo?'No disponible':fmt(filtered.reduce((n,r)=>n+r.places,0)),note:'Oferta publicada; no ocupación'},{label:profileId?'Participación en matriz nacional':'Filas institucionales con oferta',value:profileId?fmt(stats.total/totalAll*100,2)+'%':stats.positive,note:profileId?'Denominador: total de la edición':'Unidades como aparecen publicadas'},{label:'Especialidades con oferta',value:unavailableGeo?'No disponible':new Set(filtered.filter(r=>r.places>0).map(r=>r.specialty_id)).size},{label:state?'Cobertura territorial':profileId?'HHI por especialidad':'HHI institucional',value:state?'Detalle 2025':fmt(profileId?within.hhi:stats.hhi,1),note:state?'No disponible en otras ediciones':'Composición dentro de la selección actual'}]}/><Notice>Tipo: oferta publicada R1, categoría mexicana. Etapa: snapshot de la matriz o listado enlazado desde la primera vuelta; fecha de corte no identificada en la tabla. Las instituciones y hospitales aparecen al nivel publicado, sin sumar niveles jerárquicos. El aval académico de una sede no es la universidad de procedencia del aspirante.</Notice>{state&&year!==2025?<section className="panel"><Blocked>La entidad federativa solo está incorporada para los listados de sedes de 2025. No se distribuyen totales nacionales de otras ediciones mediante supuestos.</Blocked></section>:<div className="two-col"><section className="panel"><h2>{profileId?'Composición de especialidades':'Oferta por institución'} · {year}</h2><Bar dark={dark} names={dimensions.map(g=>g.name)} values={dimensions.map(g=>g.value)} label="Distribución de plazas publicadas, tabla a continuación." unit="Plazas"/></section><section className="panel"><h2>Snapshots anuales de oferta</h2><p>Observaciones publicadas por edición. No son seguimiento de plazas individuales ni una serie de ocupación.</p><Chart dark={dark} label="Oferta anual por institución en snapshots 2023–2025." option={{tooltip:{trigger:'axis'},legend:{bottom:0,type:'scroll'},grid:{left:50,right:20,top:25,bottom:80},xAxis:{type:'category',data:years},yAxis:{type:'value',name:'Plazas'},series:(profileId?allInstitutions.filter(i=>i.id===profileId):compare?allInstitutions.filter(i=>selected.includes(i.id)):allInstitutions.slice(0,4)).map((g,i)=>({name:g.name,type:'bar',itemStyle:{color:palette[i]},data:snapshotYears.map(y=>{const r=data.receiving.filter(r=>r.year===y&&r.institution_id===g.id&&(!specialty||r.specialty_id===specialty));return r.length?r.reduce((n,r)=>n+r.places,0):null;})}))}}/><p className="chart-note">Identidad longitudinal revisada únicamente para SSA, IMSS, ISSSTE y PEMEX por denominación explícita. Otras filas no se unen con coincidencias difusas.</p></section></div>}
 {!profileId&&!state&&<section className="panel"><h2>Institución × especialidad</h2><p>Ocho principales filas institucionales de la selección. Ceros explícitos en la matriz oficial.</p><Chart dark={dark} height={430} label="Heatmap de oferta institucional por especialidad. Datos exactos descargables." option={{tooltip:{position:'top'},grid:{left:15,right:20,top:15,bottom:150,containLabel:true},xAxis:{type:'category',data:matrixNames,axisLabel:{rotate:55,fontSize:8,width:115,overflow:'truncate'}},yAxis:{type:'category',data:topGroups.map(g=>g.name),axisLabel:{width:160,overflow:'truncate',fontSize:9}},visualMap:{min:0,max:Math.max(...heat.map(r=>r[2]),1),orient:'horizontal',left:'center',bottom:0,inRange:{color:['#eaf6f3','#74bfb7','#087f83']}},series:[{type:'heatmap',data:heat}]}}/></section>}
 <section className="panel"><div className="section-head"><h2>{state?'Registros de sede filtrados':'Instituciones que ofrecen plazas'}</h2><a href="#/receiving-compare">Comparar instituciones <ArrowRight size={14}/></a></div>{state?<SiteTable data={data} rows={sites}/>:<Table caption={`Oferta por fila institucional · ${year}`} headers={['Institución','Plazas','Participación (%)','Especialidades con oferta','Perfil']} rows={groups.filter(g=>g.value>0).map(g=>[g.name,fmt(g.value),fmt(stats.total?g.value/stats.total*100:0,2),new Set(records.filter(r=>r.institution_id===g.id&&r.places>0).map(r=>r.specialty_id)).size,<a href={'#/receiving/'+g.id+'?year='+year}>Abrir perfil</a>])}/>}</section>
 <section className="panel"><h2>{profileId?'¿Dónde se ofrece esta formación?':'Sedes y distribución territorial'}</h2><p>Detalle de 2025. Se muestran sedes y subsedes documentadas; no se añaden puntos al mapa sin coordenadas verificadas.</p>{sites.length?<SiteTable data={data} rows={sites}/>:<Blocked>Sin detalle territorial para esta combinación de edición y filtros.</Blocked>}<a className="text-link" href="#/hospitals">Explorar perfiles de sedes <ArrowRight size={15}/></a></section><OfferComposition rows={sites} dark={dark}/><ReceivingAnalysis year={year} institution={profileId} dark={dark} view={params.get('iview')||'concentration'} update={update}/><Notice>La concentración institucional describe la distribución de oferta. No mide superioridad académica ni desigualdad individual de acceso. Un aumento entre snapshots no equivale a plazas ocupadas o especialistas incorporados.</Notice></>;
}
function SiteTable({data,rows}:{data:PlatformData;rows:SiteRecord[]}){return <Table caption="Ofertas por código de registro publicado; sede y subsede separadas" headers={['Sede','Institución','Entidad sede','Especialidad','Plazas','Subsede / entidad','Aval académico','Fuente']} rows={rows.map(r=>[<a href={'#/hospitals/'+r.site_id}>{r.name}</a>,r.institution_name,r.state,r.specialty,fmt(r.places),r.subsite?`${r.subsite} · ${r.substate||'no identificada'}`:'No publicada',r.academic_endorsement,<SourceLink data={data} id={r.source_id} page={r.page}/>])}/>;}

function Hospitals({data,params,update,dark,id}:PageProps&{id?:string}){const q=normalized(params.get('q')||'');const state=params.get('state')||'';const institution=params.get('institution')||'';const rows=data.sites.filter(r=>(!id||r.site_id===id)&&(!state||r.state===state)&&(!institution||r.institution_id===institution)&&normalized(r.name+' '+r.specialty+' '+r.institution_name).includes(q));const title=id?(rows[0]?.name||'Sede no encontrada'):'Sedes receptoras';const report=placeReport(title,rows,data);return <><Heading label="PERFILES DE SEDES · 2025" title={title} description="Sedes y subsedes identificadas en documentos oficiales. No se infieren calidad docente, condiciones laborales, acreditación o satisfacción."><button className="secondary" onClick={()=>exportRows('sedes-filtradas',rows as unknown as Record<string,unknown>[])}>CSV</button><button className="secondary" onClick={()=>htmlReport(report)}>Informe HTML</button><button className="primary" onClick={()=>void pdfReport(report)}>PDF</button></Heading><div className="platform-filters"><label className="search"><Search size={16}/><input aria-label="Buscar hospital o sede" value={params.get('q')||''} placeholder="Nombre, institución o especialidad…" onChange={e=>update('q',e.target.value)}/></label><Select label="Entidad sede" value={state} values={unique(data.sites.map(r=>r.state))} all="Todas" onChange={v=>update('state',v)}/><label className="platform-select">Institución<select value={institution} onChange={e=>update('institution',e.target.value)}><option value="">Todas</option>{groupedPlaces(data.sites,'institution_id').map(i=><option key={i.id} value={i.id}>{i.name}</option>)}</select></label></div><Metrics values={[{label:'Plazas en registros filtrados',value:fmt(rows.reduce((n,r)=>n+r.places,0))},{label:'Sedes documentales',value:new Set(rows.map(r=>r.site_id)).size},{label:'Especialidades',value:new Set(rows.map(r=>r.specialty_id)).size},{label:'CLUES / coordenadas',value:'Sin vincular',note:'No se geolocaliza por coincidencias ambiguas'}]}/>{id&&rows.length>0&&<section className="panel"><h2>Oferta por especialidad</h2><Bar dark={dark} names={groupedPlaces(rows,'specialty_id').map(r=>r.name).reverse()} values={groupedPlaces(rows,'specialty_id').map(r=>r.value).reverse()} label="Oferta publicada de la sede por especialidad" unit="Plazas"/></section>}<section className="panel"><SiteTable data={data} rows={rows}/></section><Notice>La clave de sede se construye con institución, nombre y entidad publicados; no sustituye a CLUES. Distintos códigos de oferta pueden corresponder a una misma sede y especialidad: se conservan por separado, con control de duplicados de código. En IMSS la entidad de la subsede puede diferir de la entidad de la sede.</Notice></>;}

function Atlas({data,params,update,dark}:PageProps){const mode=params.get('mode')||'receiving';const state=params.get('state')||'';const year=mode==='receiving'?2025:academicYear(data,params);const specialty=params.get('specialty')||'';const institution=params.get('institution')||'';const sites=data.sites.filter(r=>(!specialty||r.specialty_id===specialty)&&(!institution||r.institution_id===institution));const mapRows=mode==='receiving'?groupedPlaces(sites,'state').map(r=>({name:r.name,value:r.value})):data.states!.filter(r=>r.year===year).map(r=>({name:r.state,value:r.rate}));const filteredSites=sites.filter(r=>!state||r.state===state);const stateRows=data.states!.filter(r=>r.year===year&&(!state||r.state===state));const stateReport:ReportSpec=mode==='receiving'?placeReport('Oferta receptora · '+(state||'Todas las entidades'),filteredSites,data):{title:'Procedencia académica · '+(state||'Todas las entidades'),scope:'Entidad reportada de escuela · '+year,summary:['Agregados calculados desde filas de categoría mexicana; entidad de escuela distinta de domicilio del sustentante.'],headers:['Entidad','Edición','Sustentantes','Seleccionados','Tasa (%)'],rows:stateRows.map(r=>[r.state,r.year,r.examined,r.selected,fmt(r.rate,2)]),sources:data.sources.filter(s=>s.kind==='academic'&&s.year===year),limitations:['Tasa agregada por entidad reportada, sin inferencia causal o individual.','No equiparar escalas históricas ni medias con medianas.','Se excluyen filas sin entidad identificada.','La entidad original puede contener inconsistencias; no se corrige por intuición.'],bars:stateRows.filter(r=>r.rate!=null).slice(0,12).map(r=>({name:r.state,value:r.rate!}))};return <><Heading label="ATLAS ENARM" title="La geografía de la formación." description="Explora por separado la entidad reportada de las escuelas y la entidad sede de la oferta receptora. Los filtros no crean vínculos entre personas o instituciones."/><div className="platform-filters"><Select label="Capa" value={mode} values={['receiving','academic']} onChange={v=>update('mode',v)}/>{mode==='academic'&&<Select label="Edición académica" value={String(year)} values={data.academic_years.map(String)} onChange={v=>update('year',v)}/>}<Select label="Entidad" value={state} values={unique(mapRows.map(r=>r.name))} all="Todas" onChange={v=>update('state',v)}/>{mode==='receiving'&&<><label className="platform-select">Especialidad<select value={specialty} onChange={e=>update('specialty',e.target.value)}><option value="">Todas</option>{groupedPlaces(data.sites,'specialty_id').map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label className="platform-select">Institución<select value={institution} onChange={e=>update('institution',e.target.value)}><option value="">Todas</option>{groupedPlaces(data.sites,'institution_id').map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label></> }</div><Notice>{mode==='receiving'?'Capa receptora: oferta publicada de sedes en 2025. Se asigna una sola entidad por código, la entidad de la sede; las subsedes permanecen separadas en la tabla.':'Capa de procedencia: tasa agregada de la entidad reportada para las escuelas. No describe la residencia de los sustentantes ni cobertura de atención.'} Cartografía de origen INEGI, vía geoBoundaries, límites de referencia 2020, simplificados para visualización.</Notice><section className="panel"><h2>{mode==='receiving'?'Plazas por entidad sede · 2025':`Tasa por entidad de escuela · ${year}`}</h2><MexicoMap values={mapRows} selected={state} onSelect={v=>update('state',v)} dark={dark} unit={mode==='receiving'?'plazas':'%'}/><p className="chart-note">Mapa estatal sin puntos hospitalarios aproximados. Sin datos se representa en gris. Atribución: INEGI / geoBoundaries (CC BY 3.0 IGO; ver metadatos y licencia en Fuentes). No se calculan tasas por habitante sin un denominador oficial compatible.</p></section><section className="panel">{mode==='receiving'?<SiteTable data={data} rows={filteredSites}/>:<Table caption="Agregados de entidad reportada por escuela; ponderación por sustentantes" headers={['Entidad','Edición','Sustentantes','Seleccionados','Tasa (%)','Filas']} rows={stateRows.map(r=>[r.state,r.year,fmt(r.examined),fmt(r.selected),fmt(r.rate,2),r.institutions])}/>}<div className="report-actions"><button className="primary" onClick={()=>void pdfReport(stateReport)}>Informe por entidad PDF</button><button className="secondary" onClick={()=>htmlReport(stateReport)}>HTML</button><button className="secondary" onClick={()=>exportRows('atlas-filtrado',(mode==='receiving'?filteredSites:stateRows) as unknown as Record<string,unknown>[])}>Descargar vista CSV</button></div></section></>;}

function Research({data,params,update,dark}:PageProps){const {data:research,error}=useResource<ResearchData>('research');const year=academicYear(data,params);const result=research?.results[String(year)];const rows=data.academic_records.filter(r=>r.year===year&&r.rate!=null);const view=params.get('analysis')||'association';return <><Heading label="LABORATORIO DE CIENCIA DE DATOS" title="Explorar relaciones. Hacer mejores preguntas." description="Análisis por edición de agregados institucionales: asociaciones, concentración, desigualdad geográfica y estimaciones estabilizadas."/><div className="platform-filters"><Select label="Edición" value={String(year)} values={data.academic_years.map(String)} onChange={v=>update('year',v)}/><Select label="Análisis" value={view} values={['association','concentration','pooling','pareto','variance','longitudinal']} onChange={v=>update('analysis',v)}/></div>{error?<Notice>{error}</Notice>:!result?<p role="status">Cargando resultados analíticos…</p>:<><Notice>{result.warning}</Notice>{view==='association'?<><Metrics values={[{label:'Instituciones completas',value:result.n},{label:'Spearman · volumen/tasa',value:fmt(result.spearman,3)},{label:'Pearson · volumen/tasa',value:fmt(result.pearson,3)},{label:'Tasa ponderada',value:fmt(result.weighted_rate,2)+'%'}]}/><section className="panel"><h2>Volumen y tasa institucional · {year}</h2><Chart dark={dark} label="Dispersión de sustentantes y tasa por escuela, con tabla descargable." option={{tooltip:{trigger:'item',formatter:p=>{const d=(p as unknown as {data:{value:number[];name:string}}).data;return `${d.name}<br/>Sustentantes: ${fmt(d.value[0])}<br/>Tasa: ${fmt(d.value[1],2)}%`;}},grid:{left:50,right:30,top:30,bottom:60},xAxis:{type:'value',name:'Sustentantes',nameLocation:'middle',nameGap:30},yAxis:{type:'value',min:0,max:100,name:'Tasa (%)'},series:[{type:'scatter',symbolSize:10,itemStyle:{color:palette[0],opacity:.7},data:rows.map(r=>({name:r.name,value:[r.examined,r.rate!]}))}]}}/><p className="chart-note">Spearman describe asociación monotónica; Pearson describe asociación lineal. El cociente de tasa comparte sustentantes con el eje de volumen. No se atribuye una relación causal ni calidad formativa.</p></section></>:view==='concentration'?<><Metrics values={[{label:'HHI sustentantes',value:fmt(result.concentration_examined.hhi,1)},{label:'HHI seleccionados',value:fmt(result.concentration_selected.hhi,1)},{label:'Gini de seleccionados',value:fmt(result.concentration_selected.gini,3)},{label:'Participación de cinco mayores',value:fmt(result.concentration_selected.top5,2)+'%'}]}/><section className="panel"><h2>Curvas de Lorenz de volumen institucional</h2><Chart dark={dark} label="Lorenz de sustentantes y seleccionados de las unidades publicadas." option={{tooltip:{trigger:'axis'},legend:{bottom:0},grid:{left:45,right:25,top:25,bottom:65},xAxis:{type:'value',min:0,max:1,name:'Proporción de instituciones',nameLocation:'middle',nameGap:30},yAxis:{type:'value',min:0,max:1,name:'Proporción acumulada'},series:[{name:'Sustentantes',type:'line',showSymbol:false,itemStyle:{color:palette[0]},data:result.concentration_examined.lorenz},{name:'Seleccionados',type:'line',showSymbol:false,itemStyle:{color:palette[1]},data:result.concentration_selected.lorenz},{name:'Referencia uniforme',type:'line',showSymbol:false,lineStyle:{type:'dashed',color:'#94a3b8'},data:[[0,0],[1,1]]}]}}/></section><Notice>La concentración se calcula entre las filas institucionales publicadas en esa edición; no mide desigualdad individual de oportunidades. Las denominaciones agregadas y los cambios de catálogo afectan comparaciones temporales.</Notice></>:view==='pooling'?<section className="panel"><h2>Tasa cruda y estimación beta-binomial</h2><p>{result.pooling.method as string||'Modelo empírico Bayes por edición.'}</p>{result.pooling.available?<><p>Prior estimado: α={fmt(result.pooling.alpha,3)}, β={fmt(result.pooling.beta,3)}. Intervalos posteriores al 95%, condicionados a hiperparámetros estimados.</p><Table caption="Partial pooling descriptivo; no estima valor agregado" headers={['Institución','Tasa cruda (%)','Estabilizada (%)','Intervalo posterior 95%']} rows={result.pooling.institutions!.map(r=>[data.universities.find(u=>u.id===r.id)?.name||r.id,fmt(r.raw,2),fmt(r.pooled,2),`${fmt(r.interval95[0],2)}–${fmt(r.interval95[1],2)}`])}/><Notice>{result.pooling.warning}</Notice></>:<Blocked>{result.pooling.reason}</Blocked>}</section>:view==='pareto'?<section className="panel"><h2>Frontera de Pareto · volumen y tasa</h2><p>Filas que no están dominadas simultáneamente por otra en volumen de sustentantes y tasa de selección. Comparación multidimensional, sin estimación causal de eficiencia.</p><Table caption="Frontera observada dentro de la edición" headers={['Institución','Sustentantes','Seleccionados','Tasa (%)']} rows={rows.filter(r=>result.pareto_ids.includes(r.id)).map(r=>[r.name,fmt(r.examined),fmt(r.selected),fmt(r.rate,2)])}/></section>:view==='variance'?<section className="panel"><h2>Descomposición geográfica de variación de tasas</h2>{result.variance_decomposition?<><Metrics values={[{label:'Variación total',value:fmt(result.variance_decomposition.total,3)},{label:'Entre entidades',value:fmt(result.variance_decomposition.between,3)},{label:'Dentro de entidades',value:fmt(result.variance_decomposition.within,3)},{label:'Instituciones geolocalizadas por estado',value:result.variance_decomposition.n}]}/><p>{result.variance_decomposition.unit}. Se excluyen filas sin entidad reportada. La descomposición se refiere a tasas de escuelas, no a varianza de puntajes individuales.</p></>:<Blocked>Sin entidades suficientes para descomponer la variación.</Blocked>}</section>:<section className="panel"><h2>Convergencia, movilidad, clustering y cambios estructurales</h2><Blocked>El motor exige bloques comparables y paneles balanceados. Los puntajes históricos incluyen medias, medianas y diferentes componentes; no se publican análisis longitudinales hasta validar su equivalencia. Consulta Specialty Intelligence para los métodos y controles implementados.</Blocked><AcademicLongitudinal universities={data.universities} id={params.get('longid')||''} onSelect={id=>update('longid',id)}/><a className="primary" href="#/lab">Abrir laboratorio longitudinal de especialidades</a></section>}<button className="secondary" onClick={()=>exportJSON('investigacion-'+year,result)}><ArrowDownToLine size={15}/> Descargar resultados y método JSON</button></>}</>;}


function Explorer(props:PageProps){const {data,params,update}=props;const {rows,year}=universityFilters(data,params);const group=params.get('group')||'records';const selectedColumns=(params.get('columns')||'examined,selected,rate,score').split(',');const columns=[['examined','Sustentantes'],['selected','Seleccionados'],['rate','Tasa (%)'],['score','Puntaje']] as const;const active=columns.filter(([id])=>selectedColumns.includes(id));const grouped=data.states?.filter(r=>r.year===year)||[];return <><Heading label="EXPLORADOR DE DATOS" title="De la pregunta al registro." description="Consulta tablas académicas, controla filtros y descarga exactamente las filas seleccionadas. Los valores faltantes permanecen vacíos."><button className="secondary" onClick={()=>exportRows('explorador-filtrado',rows as unknown as Record<string,unknown>[])}>CSV</button><button className="secondary" onClick={()=>exportJSON('explorador-filtrado',rows)}>JSON</button></Heading><UniversityControls {...props}/><section className="panel"><fieldset className="selection"><legend>Variables visibles</legend>{columns.map(([id,label])=><label key={id}><input type="checkbox" checked={selectedColumns.includes(id)} onChange={()=>update('columns',selectedColumns.includes(id)?selectedColumns.filter(c=>c!==id).join(','):[...selectedColumns,id].join(','))}/>{label}</label>)}</fieldset><Table caption={`Registros filtrados · ${year}`} headers={['Institución','Entidad',...active.map(c=>c[1]),'Estadístico','Fuente']} rows={rows.map(r=>[r.name,r.state||'No identificada',...active.map(([key])=>fmt(r[key],key==='rate'||key==='score'?3:0)),r.score_statistic==='median'?'Mediana':'Media',<SourceLink id={r.source_id} data={data} page={r.page}/>])}/></section><a className="text-link" href="#/receiving">Explorar registros de plazas y sedes <ArrowRight size={15}/></a><Notice>Las descargas contienen los registros completos filtrados, aunque la tabla use paginación. La selección de variables modifica la vista y se conserva en la URL. Las tablas receptoras tienen filtros y exportaciones en su propio módulo.</Notice></>;}

function Reports({data,params,update}:PageProps){const id=params.get('university')||data.universities[0]?.id;const u=data.universities.find(u=>u.id===id||u.identity_link?.alias_ids.includes(id));return <><Heading label="REPORTES DESCARGABLES" title="Evidencia lista para compartir." description="Informes por universidad, institución, especialidad, sede y entidad. Datos, figuras, metodología, limitaciones y referencias oficiales en un solo documento."/><section className="panel"><h2>Informe por universidad de procedencia</h2><label className="platform-select">Perfil<select value={id} onChange={e=>update('university',e.target.value)}>{data.universities.map(u=><option key={u.id} value={u.id}>{u.name} · {u.state}</option>)}</select></label>{u&&<div className="report-actions"><button className="primary" onClick={()=>void pdfReport(universityReport(u,data))}>Descargar PDF</button><button className="secondary" onClick={()=>htmlReport(universityReport(u,data))}>HTML autónomo</button><button className="secondary" onClick={()=>exportRows('perfil-universidad',u.records as unknown as Record<string,unknown>[])}>CSV</button></div>}</section><div className="module-grid">{[['Institución receptora','Selecciona institución, edición y especialidad; exporta PDF, HTML o CSV.','/receiving'],['Especialidad','Historia observada, mínimos y máximos con metodología y fuentes.','/specialty'],['Hospital / sede','Oferta documentada, aval académico y separación de sede y subsede.','/hospitals'],['Entidad federativa','Filtra el atlas por estado para exportar sus registros.','/atlas']].map(([h,p,path])=><a className="panel module-card" href={'#'+path} key={path}><FileText size={22}/><h2>{h}</h2><p>{p}</p><span>Abrir módulo <ArrowRight size={15}/></span></a>)}</div><Notice>Los informes identifican cálculos propios y datos oficiales. No generan conclusiones causales ni pronósticos automáticos. Los datos personales de folios de aspirantes no se descargan ni procesan.</Notice></>;}

function AllSources({data}:PageProps){return <><Heading label="FUENTES Y ACTUALIZACIONES" title="Un observatorio que se puede auditar." description="Archivos oficiales preservados, extracción con controles y catálogo de cobertura. La fecha de descarga no sustituye al corte del documento."><button className="secondary" onClick={()=>exportJSON('inventario-oficial',data.sources)}>Inventario JSON</button></Heading><Notice>Académicos: {data.academic_years[0]}–{data.academic_years.at(-1)}. Matrices de oferta: 2023–2025. Sedes: 2025. Puntajes de especialidades: 2022–2025. Cada conjunto tiene su propia unidad, población y etapa. <a href="#/sources">Ver auditoría de puntajes</a>.</Notice><section className="panel"><Table caption="Inventario de fuentes descargadas y estado de extracción" headers={['Edición','Conjunto','Documento','Estado','Filas','SHA-256','Descarga UTC']} rows={data.sources.map(s=>[s.year,s.kind,<a href={s.url} target="_blank" rel="noreferrer">{s.title||s.file.split('/').at(-1)} <ExternalLink size={12}/></a>,s.status,fmt(s.rows),<code className="hash-short" title={s.sha256}>{s.sha256}</code>,s.downloaded_at])}/></section><section className="panel"><h2>Estado del sistema de actualización</h2><p>GitHub Actions revisa las fuentes conocidas semanalmente y permite ejecución manual. Los cambios se archivan en un reporte de diferencias. No se reemplaza un archivo validado ni se publica una extracción nueva sin superar controles de esquema, hashes y conciliación.</p><p>El despliegue permanece pendiente de acceso al repositorio GitHub objetivo. El sitio conserva el último conjunto aprobado si una revisión o validación falla.</p></section><section className="panel"><h2>Cartografía y atribución</h2><p>INEGI, límites de referencia 2020, distribución a través de geoBoundaries (MEX-ADM1-31927357). Licencia reportada por el catálogo: CC BY 3.0 IGO. Geometría simplificada con preservación de topología; no se atribuyen coordenadas a hospitales.</p><a href="https://www.geoboundaries.org/api/current/gbOpen/MEX/ADM1/" target="_blank" rel="noreferrer">Metadatos geográficos <ExternalLink size={12}/></a></section></>;}
function Methodology(){return <><Heading label="METODOLOGÍA GENERAL · V2.0.0" title="Definiciones antes que conclusiones." description="Tres unidades separadas: procedencia académica, especialidad y oferta receptora. La transparencia incluye qué análisis todavía no se puede sostener."/><div className="dictionary">{[['Unidad académica','Escuela o facultad reportada para sustentantes de categoría mexicana. Identidad por entidad y denominación normalizada exacta. No se fusionan campus por coincidencia difusa.'],['Tasa de selección','100 × seleccionados / sustentantes de la misma fila y edición. Intervalo Wilson 95% bajo supuesto binomial descriptivo. No es probabilidad individual futura ni medida causal de calidad.'],['Promedio nacional calculado','Media ponderada por sustentantes solo cuando todas las filas tienen medias y puntajes disponibles. No se promedian medianas históricas, y no se equiparan escalas entre años.'],['Oferta receptora','Plazas publicadas R1, categoría mexicana. Matriz por institución × especialidad. Los listados de sedes son un detalle alternativo y no se suman a la matriz. No equivalen a asignadas, aceptadas, ocupadas o residentes incorporados.'],['Concentración','HHI = suma de participaciones al cuadrado × 10 000. Gini y Lorenz describen distribución entre unidades publicadas. Participaciones de tres y cinco mayores. La composición del catálogo limita comparaciones históricas.'],['Estabilización beta-binomial','Partial pooling por edición. Hiperparámetros estimados por máxima verosimilitud marginal, posterior beta para cada institución. Intervalos condicionados al prior estimado; no capturan toda la incertidumbre de hiperparámetros.'],['Desigualdad territorial','Descomposición ponderada de variación de tasas entre entidades y dentro de entidades. Entidad de escuela distinta de residencia del sustentante. En plazas se usa entidad de sede documentada, separando subsedes.'],['Geolocalización','Polígonos estatales con origen INEGI y metadatos geoBoundaries. CLUES y coordenadas de hospitales pendientes de enlace verificado. Los nombres de hospitales no se convierten en ubicaciones aproximadas.'],['Comparabilidad y predicción','Cambios de escala, medias/medianas, composición y selección se conservan explícitos. No se habilitan modelos longitudinales o pronósticos por tener muchos años sin revisión de equivalencia.'],['Datos faltantes','Null significa no disponible o no incorporado. Cero se conserva solo cuando la fuente publica cero. Las filas de totales no se suman nuevamente a sus componentes.'],['Relaciones institucionales','Aval académico, institución receptora, sede, subsede y universidad de procedencia son campos diferentes. No se infieren convenios o trayectorias de personas de totales marginales.'],['Reproducibilidad','Documentos originales y SHA-256, parsers por formato, controles de dominio/unicidad, conciliación de filas/columnas, JSON estático, DuckDB y Parquet. Fixtures de pruebas nunca se publican como ENARM real.']].map(([title,text])=><section className="panel" key={title}><h2>{title}</h2><p>{text}</p><small>Versión 2.0.0 · ámbito y fuentes visibles en cada módulo</small></section>)}</div><section className="panel"><h2>Correcciones y participación</h2><p>Reporta errores documentando módulo, edición, fuente y fila afectada en las incidencias del repositorio. No adjuntes folios ni datos personales de aspirantes.</p><a href="https://github.com/doctordatamx/enarmwatcher/issues" target="_blank" rel="noreferrer">Canal de correcciones en GitHub <ExternalLink size={14}/></a><p>El repositorio debe estar disponible para que el canal funcione; no se ha verificado acceso público desde este entorno.</p><a href="#/methods">Diccionario específico de especialidades <ArrowRight size={14}/></a></section></>;}
